effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat7;
vec3 u_xlat9;
float u_xlat13;
float u_xlat19;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.xy = vec2(1.0, 1.0) / _resolution.xy;
    u_xlat1.z = (-u_xlat1.x);
    u_xlat2 = u_xlat1.zyxy + acScreenNorm.xyxy;
    u_xlat3.xyz = texture(inputImg, u_xlat2.xy).xyz;
    u_xlat13 = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat13 = sqrt(u_xlat13);
    u_xlat3.xyz = (-u_xlat1.xyx);
    u_xlat3.w = 0.0;
    u_xlat3 = u_xlat3.zwxy + acScreenNorm.xyxy;
    u_xlat4.xyz = texture(inputImg, u_xlat3.xy).xyz;
    u_xlat2.x = dot(u_xlat4.xyz, u_xlat4.xyz);
    u_xlat3.xyz = texture(inputImg, u_xlat3.zw).xyz;
    u_xlat2.y = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat1.w = 0.0;
    u_xlat3 = u_xlat1.wyxw + acScreenNorm.xyxy;
    u_xlat4.xyz = texture(inputImg, u_xlat3.xy).xyz;
    u_xlat3.x = dot(u_xlat4.xyz, u_xlat4.xyz);
    u_xlat3.x = sqrt(u_xlat3.x);
    u_xlat4 = u_xlat1.wyxy * vec4(1.0, -1.0, 1.0, -1.0) + acScreenNorm.xyxy;
    u_xlat1.xyw = texture(inputImg, u_xlat4.xy).xyz;
    u_xlat1.x = dot(u_xlat1.xyw, u_xlat1.xyw);
    u_xlat5.xyz = texture(inputImg, u_xlat2.zw).xyz;
    u_xlat1.y = dot(u_xlat5.xyz, u_xlat5.xyz);
    u_xlat9.xyz = texture(inputImg, u_xlat3.zw).xyz;
    u_xlat1.w = dot(u_xlat9.xyz, u_xlat9.xyz);
    u_xlat1.xyw = sqrt(u_xlat1.xyw);
    u_xlat9.xyz = texture(inputImg, u_xlat4.zw).xyz;
    u_xlat2.z = dot(u_xlat9.xyz, u_xlat9.xyz);
    u_xlat2.xyz = sqrt(u_xlat2.xyz);
    u_xlat2.x = u_xlat2.x * 2.0 + u_xlat13;
    u_xlat2.x = u_xlat2.y + u_xlat2.x;
    u_xlat2.x = (-u_xlat1.y) + u_xlat2.x;
    u_xlat19 = (-u_xlat1.w) * 2.0 + u_xlat2.x;
    u_xlat19 = (-u_xlat2.z) + u_xlat19;
    u_xlat13 = (-u_xlat3.x) * 2.0 + (-u_xlat13);
    u_xlat7.x = (-u_xlat1.y) + u_xlat13;
    u_xlat7.x = u_xlat2.y + u_xlat7.x;
    u_xlat1.x = u_xlat1.x * 2.0 + u_xlat7.x;
    u_xlat1.x = u_xlat2.z + u_xlat1.x;
    u_xlat1.x = u_xlat1.x * u_xlat1.x;
    u_xlat1.x = u_xlat19 * u_xlat19 + u_xlat1.x;
    u_xlat1.x = sqrt(u_xlat1.x);
    u_xlat1.x = u_xlat1.x + (-_threshold);
    u_xlat7.xyz = u_xlat0.xyz * u_xlat1.xxx;
    u_xlatb2.x = int(_invert)==1;
    u_xlat1.x = (-u_xlat1.x) + 1.0;
    u_xlat1.xyz = (u_xlatb2.x) ? u_xlat1.xxx : u_xlat7.xyz;
    u_xlat19 = (-_blend_with_original) + 1.0;
    u_xlat1.xyz = u_xlat1.xyz * vec3(u_xlat19);
    u_xlat1.xyz = u_xlat0.xyz * vec3(vec3(_blend_with_original, _blend_with_original, _blend_with_original)) + u_xlat1.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1.w = u_xlat0.w;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat5 = u_xlat0 * u_xlat5;
        u_xlat3 = u_xlat3 * u_xlat4 + u_xlat5;
        u_xlat0.x = u_xlat4.x * u_xlat3.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat0.x : u_xlat3.w;
        fragColor.xyz = u_xlat3.xyz;
    } else {
        fragColor.xyz = u_xlat1.xyz;
        fragColor.w = u_xlat0.w;
    }
    return;
}
